const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountTeacherAdmin(host,{call,isActive=()=>host.isConnected}={}){
 let disposed=false,busy=false,lookup=0;
 const active=()=>!disposed&&host.isConnected&&isActive();
 host.innerHTML='<section class="teacher-admin"><a class="button secondary" href="#lesson?view=teacher&return=owner">Кабинет преподавателя</a><h2>Назначить преподавателя</h2><p class="cabinet-muted">Назначьте преподавателя по нику его зарегистрированного аккаунта SALAH. Роль сохраняется на сервере. Доступ к новым учебным разделам пока остаётся закрытым.</p><form data-find-teacher><label>Ник в SALAH<input type="text" name="nickname" autocomplete="off" minlength="2" maxlength="40" required placeholder="Введите ник преподавателя"></label><button type="submit" class="button secondary">Найти аккаунт</button></form><p role="status" aria-live="polite" data-teacher-status></p><div data-teacher-profile></div><h3>Назначенные преподаватели</h3><div data-teacher-roster></div><p class="cabinet-muted">Роль можно отозвать в любой момент. Права владельца и администратора SALAH не передаются.</p></section>';
 const form=host.querySelector('form'),status=host.querySelector('[data-teacher-status]'),profile=host.querySelector('[data-teacher-profile]'),roster=host.querySelector('[data-teacher-roster]');
 const controls=value=>{busy=value;for(const b of host.querySelectorAll('button,input'))b.disabled=value;};
 function card(account){const el=host.ownerDocument.createElement('article');el.className='teacher-profile cabinet-lesson-card';el.innerHTML='<div class="teacher-profile-heading"><div class="cabinet-pupil-avatar" aria-hidden="true">'+escape((account.nickname||'У').slice(0,1).toUpperCase())+'</div><div><h3>'+escape(account.nickname)+'</h3><p class="teacher-email">'+escape((account.emailHint||'Аккаунт')+' · '+account.id.slice(-6))+'</p></div></div><span class="teacher-state '+(account.active?'is-active':'')+'">'+(account.active?'Преподаватель':account.revision?'Доступ отозван':'Доступ не назначен')+'</span><div class="cabinet-card-actions"></div>';return el;}
 function button(container,label,handler,secondary=false){const b=host.ownerDocument.createElement('button');b.type='button';b.className='button'+(secondary?' secondary':'');b.textContent=label;b.onclick=handler;container.append(b);return b;}
 async function change(account,grant){if(busy)return;controls(true);status.textContent=grant?'Назначаем преподавателя…':'Отзываем доступ…';try{await call(grant?'teacher-assign':'teacher-revoke',{userId:account.id,expectedRevision:account.revision});if(!active())return;profile.replaceChildren();form.reset();lookup++;status.textContent=grant?'Роль преподавателя назначена. Учебные разделы пока остаются закрытыми.':'Роль преподавателя отозвана.';await load();}catch(error){if(active())status.textContent=error.message;}finally{if(active())controls(false);}}
 function drawProfile(account){profile.replaceChildren();const el=card(account),actions=el.querySelector('.cabinet-card-actions');if(account.active){const p=host.ownerDocument.createElement('p');p.className='cabinet-muted';p.textContent='Этот аккаунт уже назначен преподавателем.';el.append(p);}else button(actions,account.revision?'Назначить снова':'Назначить преподавателем',()=>void change(account,true));profile.append(el);}
 async function load(){const result=await call('teacher-list');if(!active())return;roster.replaceChildren();if(!result.teachers.length){const p=host.ownerDocument.createElement('p');p.className='cabinet-empty';p.textContent='Пока нет назначенных преподавателей.';roster.append(p);return;}for(const account of result.teachers){const el=card(account),actions=el.querySelector('.cabinet-card-actions');if(account.active)button(actions,'Отозвать доступ',()=>{if(busy)return;actions.replaceChildren();const p=host.ownerDocument.createElement('p');p.className='teacher-revoke-note';p.textContent='Закрыть доступ '+account.nickname+' к роли преподавателя?';actions.append(p);button(actions,'Подтвердить отзыв',()=>void change(account,false));button(actions,'Отмена',()=>void reload(),true);},true);else button(actions,'Назначить снова',()=>drawProfile(account),true);roster.append(el);}}
 async function reload(){if(busy)return;controls(true);try{await load();}catch(error){if(active()){status.textContent=error.message;roster.replaceChildren();button(roster,'Повторить загрузку',()=>void reload(),true);}}finally{if(active())controls(false);}}
 form.onsubmit=async event=>{event.preventDefault();if(busy)return;const ticket=++lookup;controls(true);profile.replaceChildren();status.textContent='Ищем аккаунт…';try{const result=await call('teacher-lookup',{nickname:form.elements.nickname.value.trim()});if(!active()||ticket!==lookup)return;profile.replaceChildren();for(const account of result.accounts){const el=card(account);if(!account.active)button(el.querySelector('.cabinet-card-actions'),account.revision?'Назначить снова':'Назначить преподавателем',()=>void change(account,true));profile.append(el);}status.textContent=result.truncated?'Много совпадений. Уточните ник.':result.accounts.length>1?'Найдено несколько аккаунтов. Выберите нужный профиль и подтвердите назначение.':'Проверьте найденный профиль, затем подтвердите назначение.';}catch(error){if(active()&&ticket===lookup)status.textContent=error.message;}finally{if(active())controls(false);}};
 form.elements.nickname.oninput=()=>{lookup++;profile.replaceChildren();status.textContent='';};
 void reload();return()=>{disposed=true;lookup++;host.replaceChildren();};
}
